globalThis.FiggieTerminalAssets = {"html": "\n    <div id=\"figgie-fast\" aria-label=\"Live Figgie terminal\">\n      <header class=\"ff-header\">\n        <div class=\"ff-brand\">\n          <strong>figgie<span>pro</span></strong\n          ><span class=\"ff-workspace\">All markets</span>\n        </div>\n        <span class=\"ff-replay\" id=\"session\">Connecting\u2026</span\n        ><button id=\"show-figgie\" type=\"button\">Show Figgie</button>\n      </header>\n      <div class=\"ff-account\">\n        <span>Cash <b id=\"cash\">\u2014</b></span\n        ><span>Cards <b id=\"cards\">\u2014</b></span\n        ><span class=\"ff-round-pnl\"\n          ><span id=\"round-pnl-label\">Round P&amp;L est.</span> <b id=\"round-pnl\">\u2014</b></span\n        ><span id=\"connection\">Connecting to Figgie\u2026</span\n        ><span id=\"recording-state\" title=\"Game events are saved locally in this Chrome profile\"\n          >REC \u00b7 starting</span\n        ><label class=\"ff-keys\"\n          ><input\n            type=\"checkbox\"\n            id=\"ff-keys\"\n            title=\"1/2 Spades \u00b7 3/4 Clubs \u00b7 5/6 Diamonds \u00b7 7/8 Hearts \u2014 Buy/Sell\"\n          />\n          Keys 1\u20138</label\n        >\n      </div>\n      <section class=\"ff-inventory\" aria-label=\"Consolidated inventory\">\n        <div class=\"ff-inventory-label\">My inventory<span id=\"inventory-total\">\u2014</span></div>\n        <div id=\"ff-inventory-items\"></div>\n        <div class=\"ff-inventory-value\">\n          <span id=\"inventory-valuation-label\">Settlement est.</span\n          ><strong id=\"ff-inventory-ev\">\u2014</strong><span>If settled now</span>\n        </div>\n      </section>\n      <div\n        id=\"buyer-legend\"\n        class=\"ff-buyer-legend\"\n        aria-label=\"Player colors for chart buyers and quote owners\"\n      ></div>\n      <div class=\"ff-model-workspace\">\n        <main\n          class=\"ff-markets\"\n          id=\"ff-markets\"\n          aria-label=\"Four live suit charts and trading controls\"\n        ></main>\n        <aside class=\"ff-model-panel\" aria-label=\"Live Bayesian model\">\n          <section class=\"ff-pnl-panel\" aria-label=\"Net round profit and loss\">\n            <div class=\"ff-section-heading\">\n              Net round P&amp;L <span id=\"pnl-state\">Est.</span><strong id=\"pnl-total\">\u2014</strong>\n            </div>\n            <div class=\"ff-scenario-heading\">\n              P&amp;L by goal <span id=\"pnl-scenarios-state\">Est. \u00b7 settle now</span>\n            </div>\n            <div\n              id=\"pnl-scenarios\"\n              class=\"ff-pnl-scenarios\"\n              aria-label=\"Estimated net round P&amp;L for each possible goal suit\"\n            ></div>\n          </section>\n          <div class=\"ff-section-heading\">Bayesian model<span id=\"model-kind\">Waiting</span></div>\n          <div class=\"ff-model-caption\">\n            <span id=\"goal-odds-caption\">Goal-suit probabilities</span\n            ><label class=\"ff-model-toggle\"\n              ><input type=\"checkbox\" id=\"opponent-model\" checked /> Opponents</label\n            >\n          </div>\n          <div id=\"model-confidence\" class=\"ff-confidence\">\n            Opponent policy priors \u00b7 not yet calibrated\n          </div>\n          <div id=\"ff-model-odds\"></div>\n          <div class=\"ff-model-caption\">Model prices <span>chips / card</span></div>\n          <table class=\"ff-model-prices\">\n            <thead>\n              <tr>\n                <th>Suit</th>\n                <th title=\"10 \u00d7 goal probability; no leader bonus\">Base fair</th>\n                <th>Buy value</th>\n                <th>Sell value</th>\n              </tr>\n            </thead>\n            <tbody id=\"ff-model-prices\"></tbody>\n          </table>\n          <div class=\"ff-model-estimate\">\n            <span>Inventory payout EV</span><b id=\"ff-payout-ev\">\u2014</b><span>Card payout</span\n            ><span id=\"ff-base-ev\">\u2014</span\n            ><span title=\"Most goal cards wins; tied leaders split the bonus\">Leader bonus</span\n            ><span id=\"ff-bonus-ev\">\u2014</span>\n          </div>\n          <div class=\"ff-model-footnote\">\n            Base fair = 10 \u00d7 goal odds. Buy/sell values add the marginal bonus change. No bonus P&L\n            excludes that uncertain bonus.\n          </div>\n          <details class=\"ff-model-method\">\n            <summary>Evidence &amp; assumptions</summary>\n            <dl>\n              <dt>Starting hand</dt>\n              <dd id=\"starting-hand\">\u2014</dd>\n              <dt>Observed fills</dt>\n              <dd id=\"evidence\">\u2014</dd>\n              <dt>Posterior</dt>\n              <dd>\n                Exact legal-deal baseline, executed card movements and qualified observed asks, plus\n                sampled opponent behavior. In four-player Medium-bot games, sustained accumulators\n                shift estimated hidden holdings and bonus shares without changing goal odds.\n                Repeated pennies form one episode; your own choices do not confirm themselves. Cards\n                percentages exclude behavior.\n              </dd>\n              <dt>Pricing</dt>\n              <dd>\n                Immediate settlement value includes the leader bonus. Resting EV combines fill\n                probability with state-dependent counterparty selection. The horizon ends after 10\n                seconds, a reset, or loss of top position. It excludes later fills after being\n                outbid and future resale.\n              </dd>\n              <dt>Scope</dt>\n              <dd>\n                Opponent policies and initial fill rates are assumptions until scored on revealed\n                rounds. Hard evidence is exact; behavior and payout estimates use sampled worlds.\n                Only visible game data is recorded. Brief book changes may be missed by the DOM\n                adapter.\n              </dd>\n            </dl>\n          </details>\n        </aside>\n      </div>\n      <div class=\"ff-notice\" aria-live=\"polite\" id=\"ff-notice\">\n        Waiting for a complete game snapshot.\n      </div>\n      <section class=\"ff-lower\">\n        <div class=\"ff-flow\">\n          <div class=\"ff-section-heading\">\n            Player flow <span>Net cards traded since the deal</span>\n          </div>\n          <table>\n            <thead>\n              <tr>\n                <th>Player</th>\n                <th><span class=\"ff-suit-icon ff-suit-black\">\u2660</span></th>\n                <th><span class=\"ff-suit-icon ff-suit-black\">\u2663</span></th>\n                <th><span class=\"ff-suit-icon ff-suit-red\">\u2666</span></th>\n                <th><span class=\"ff-suit-icon ff-suit-red\">\u2665</span></th>\n              </tr>\n            </thead>\n            <tbody id=\"flow\"></tbody>\n          </table>\n        </div>\n        <div class=\"ff-actions\">\n          <div class=\"ff-section-heading\">Recent trades <span>Buyer \u2190 seller</span></div>\n          <div class=\"ff-trade-head\">\n            <span>Fill</span><span>Suit</span><span>Buyer</span><span>Seller</span\n            ><span>Price</span>\n          </div>\n          <div\n            id=\"recent-trades\"\n            tabindex=\"0\"\n            aria-label=\"Recent trades, newest first. Scroll horizontally for older trades.\"\n          ></div>\n        </div>\n      </section>\n      <details class=\"diagnostics\">\n        <summary>Recordings &amp; diagnostics</summary>\n        <div class=\"ff-record-tools\">\n          <button type=\"button\" id=\"export-recording\">Export this round</button\n          ><button type=\"button\" id=\"export-all-recordings\">Export all rounds</button\n          ><span id=\"recording-details\">Waiting for game</span>\n        </div>\n        <div id=\"round-result-state\"></div>\n        <div class=\"ff-result-input\">\n          <select id=\"revealed-goal\" aria-label=\"Revealed goal suit\">\n            <option value=\"\">Revealed goal\u2026</option>\n            <option value=\"s\">\u2660 Spades</option>\n            <option value=\"c\">\u2663 Clubs</option>\n            <option value=\"d\">\u2666 Diamonds</option>\n            <option value=\"h\">\u2665 Hearts</option></select\n          ><button type=\"button\" id=\"save-revealed-goal\">Record result</button>\n        </div>\n        <textarea id=\"diagnostics\" readonly aria-label=\"Live adapter diagnostics\"></textarea>\n      </details>\n      <footer>\n        <span id=\"update-state\">Waiting for source</span\n        ><span>Every execution clears all quotes.</span\n        ><span>Manual actions only \u00b7 model runs locally</span>\n      </footer>\n    </div>\n  ", "css": "/*\n * Figgie Terminal styles.\n *\n * build.py bundles this file into ui-assets.js and content.js injects it into the\n * terminal's shadow root. Apart from the page and host rules at the top, every rule is\n * scoped to #figgie-fast.\n *\n * Rules are grouped by component, in page order. A selector is declared once in the base\n * rules and at most once in each media block; within a rule, declarations run from layout\n * through box to text. The base rules hold what every layout shares. The media blocks at\n * the end adapt them and are ordered so that a later block wins wherever two apply at\n * once. Two of them set the page layout: Compact, where the page scrolls, and Desktop,\n * where trading rows fill the viewport.\n */\n\n/* \u2500\u2500 Standalone page \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Only terminal.html opened on its own has a document root to style; inside the shadow root\n   these two rules match nothing. */\n:root {\n  color-scheme: dark;\n}\nbody {\n  margin: 0;\n  background: #0d1619;\n}\n\n/* \u2500\u2500 Host and root \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* The host fills its frame and never scrolls on a desktop viewport: the root grid keeps the\n   charts and controls on screen. */\n:host {\n  display: block;\n  height: 100%;\n  overflow: hidden;\n  color-scheme: dark;\n}\n/* Color tokens, type and the grid of page rows. */\n#figgie-fast {\n  --ff-bg: #1b272d;\n  --ff-panel: #223138;\n  --ff-soft: #2b3c43;\n  --ff-ink: #f0f5f4;\n  --ff-dim: #b3c2c5;\n  --ff-line: #3b4b52;\n  --ff-green: #85e6bf;\n  --ff-green-bg: #214a3e;\n  --ff-red: #ff9aaa;\n  --ff-red-bg: #4b303b;\n  --ff-chart: #9ccfe4;\n  display: grid;\n  grid-template-rows: 38px 26px 46px 24px minmax(0, 1fr) 114px 28px 20px;\n  height: 100%;\n  min-height: 0;\n  overflow: hidden;\n  background: var(--ff-bg);\n  color: var(--ff-ink);\n  font:\n    13px/1.4 -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    sans-serif;\n  font-variant-numeric: tabular-nums;\n}\n#figgie-fast * {\n  box-sizing: border-box;\n}\n\n/* \u2500\u2500 Element defaults \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast button {\n  font: inherit;\n  cursor: pointer;\n}\n#figgie-fast input {\n  font: inherit;\n}\n#figgie-fast input[type='checkbox'] {\n  width: 14px;\n  height: 14px;\n  margin: 0;\n  accent-color: var(--ff-green);\n}\n#figgie-fast strong {\n  color: var(--ff-ink);\n  font-size: 22px;\n  font-weight: 600;\n  letter-spacing: -0.8px;\n}\n#figgie-fast strong > span {\n  margin-left: 5px;\n  color: var(--ff-green);\n  font-size: 11px;\n  letter-spacing: 0;\n}\n#figgie-fast b {\n  color: var(--ff-ink);\n  font-weight: 500;\n}\n#figgie-fast kbd {\n  margin-left: 5px;\n  padding: 1px 4px;\n  border: 1px solid currentColor;\n  border-radius: 3px;\n  opacity: 0.7;\n  font:\n    10px/1.4 ui-monospace,\n    monospace;\n}\n#figgie-fast table {\n  border-collapse: collapse;\n  width: 100%;\n  font-size: 12px;\n}\n#figgie-fast th {\n  padding: 6px 14px;\n  border-bottom: 1px solid var(--ff-line);\n  color: var(--ff-dim);\n  font-size: 11px;\n  font-weight: 400;\n  text-align: left;\n}\n#figgie-fast td {\n  padding: 6px 14px;\n  border-bottom: 1px solid var(--ff-line);\n}\n#figgie-fast th:not(:first-child),\n#figgie-fast td:not(:first-child) {\n  text-align: right;\n}\n\n/* \u2500\u2500 Shared pieces \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-section-heading {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 10px 14px;\n  border-bottom: 1px solid var(--ff-line);\n  font-size: 12px;\n  font-weight: 500;\n}\n#figgie-fast .ff-section-heading span {\n  color: var(--ff-dim);\n  font-size: 11px;\n  font-weight: 400;\n}\n#figgie-fast .ff-suit-icon {\n  display: inline-flex;\n  flex-shrink: 0;\n  align-items: center;\n  justify-content: center;\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 1.2;\n}\n#figgie-fast .ff-suit-red {\n  color: #ff8799;\n}\n/* Black suits sit on a light chip so they stay legible on the dark surfaces. */\n#figgie-fast .ff-suit-black {\n  padding: 0 3px;\n  border-radius: 3px;\n  background: #d5e0e4;\n  color: #10191e;\n}\n\n/* \u2500\u2500 Header \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  min-height: 0;\n  padding: 4px 12px;\n  border-bottom: 1px solid var(--ff-line);\n}\n#figgie-fast .ff-brand {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  color: var(--ff-green);\n}\n#figgie-fast .ff-header strong {\n  font-size: 20px;\n}\n#figgie-fast .ff-workspace {\n  margin-left: 18px;\n  font-size: 12px;\n  font-weight: 500;\n}\n#figgie-fast .ff-replay {\n  margin-left: auto;\n  color: var(--ff-dim);\n  font-size: 11px;\n  white-space: nowrap;\n}\n#figgie-fast #show-figgie {\n  padding: 4px 9px;\n  border: 1px solid var(--ff-line);\n  border-radius: 4px;\n  background: var(--ff-soft);\n  color: var(--ff-ink);\n  font: inherit;\n  font-size: 11px;\n  white-space: nowrap;\n}\n\n/* \u2500\u2500 Account bar \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-account {\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  padding: 3px 12px;\n  border-bottom: 1px solid var(--ff-line);\n  color: var(--ff-dim);\n  font-size: 12px;\n}\n#figgie-fast .ff-account b {\n  margin-left: 4px;\n}\n#figgie-fast .ff-round-pnl {\n  margin-left: 2px;\n  color: var(--ff-dim);\n  white-space: nowrap;\n}\n#figgie-fast .ff-round-pnl b {\n  font-size: 16px;\n  font-weight: 650;\n}\n#figgie-fast .ff-keys {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 11px;\n  white-space: nowrap;\n}\n\n/* \u2500\u2500 Inventory strip \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-inventory {\n  display: grid;\n  grid-template-columns: 85px minmax(0, 1fr) 100px;\n  align-items: center;\n  gap: 10px;\n  padding: 4px 12px;\n  border-bottom: 1px solid var(--ff-line);\n  background: var(--ff-panel);\n}\n#figgie-fast .ff-inventory-label {\n  font-size: 12px;\n  font-weight: 500;\n}\n#figgie-fast .ff-inventory-label span {\n  display: block;\n  color: var(--ff-dim);\n  font-size: 11px;\n  font-weight: 400;\n}\n#figgie-fast #ff-inventory-items {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 12px;\n}\n#figgie-fast .ff-inventory-item {\n  min-width: 0;\n  padding-left: 14px;\n  border-left: 1px solid var(--ff-line);\n}\n#figgie-fast .ff-inventory-item > span {\n  display: inline;\n  color: var(--ff-dim);\n  font-size: 11px;\n  white-space: nowrap;\n}\n#figgie-fast .ff-inventory-item .ff-suit-icon {\n  font-size: 16px;\n}\n#figgie-fast .ff-inventory-item > div {\n  display: inline-flex;\n  align-items: baseline;\n  gap: 8px;\n  margin: 0 0 0 8px;\n}\n#figgie-fast .ff-inventory-item strong {\n  font-size: 21px;\n  font-weight: 500;\n  letter-spacing: -0.5px;\n}\n#figgie-fast .ff-inventory-item small {\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-inventory-value {\n  color: var(--ff-dim);\n  font-size: 11px;\n  text-align: right;\n}\n#figgie-fast .ff-inventory-value strong {\n  display: inline;\n  margin-left: 6px;\n  color: var(--ff-ink);\n  font-size: 19px;\n  font-weight: 500;\n  letter-spacing: -0.5px;\n}\n#figgie-fast .ff-inventory-value > span {\n  display: none;\n}\n#figgie-fast #inventory-valuation-label {\n  display: inline;\n  font-size: 10px;\n}\n\n/* \u2500\u2500 Player legend \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Player identity matches the chart buyers and quote-owner badges. */\n#figgie-fast .ff-buyer-legend {\n  display: flex;\n  align-items: center;\n  gap: 8px 18px;\n  padding: 3px 12px;\n  overflow: hidden;\n  border-bottom: 1px solid var(--ff-line);\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-buyer-key {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--ff-ink);\n}\n#figgie-fast .ff-buyer-key i {\n  display: inline-block;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n}\n\n/* \u2500\u2500 Workspace \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Markets on the left, the model panel on the right. */\n#figgie-fast .ff-model-workspace {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 260px;\n  min-height: 0;\n  overflow: hidden;\n}\n#figgie-fast .ff-markets {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  grid-template-rows: repeat(2, minmax(0, 1fr));\n  min-height: 0;\n}\n\n/* \u2500\u2500 Market panel \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-market {\n  display: grid;\n  grid-template-rows: 28px 18px minmax(28px, 1fr) 14px 90px 78px;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n  border-bottom: 1px solid var(--ff-line);\n  background: #1e2c32;\n}\n#figgie-fast .ff-market:nth-child(odd) {\n  border-right: 1px solid var(--ff-line);\n}\n#figgie-fast .ff-market:nth-child(2),\n#figgie-fast .ff-market:nth-child(3) {\n  background: #202e35;\n}\n#figgie-fast .ff-market-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 3px 12px;\n}\n#figgie-fast .ff-market-name {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 15px;\n  font-weight: 600;\n}\n#figgie-fast .ff-market-name .ff-suit-icon {\n  width: 25px;\n  height: 25px;\n  font-size: 21px;\n}\n#figgie-fast .ff-market-name .ff-suit-red {\n  border: 1px solid #ff879935;\n  border-radius: 3px;\n  background: #ff879917;\n}\n#figgie-fast .ff-market-numbers {\n  display: flex;\n  gap: 10px;\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-market-numbers b {\n  margin-left: 5px;\n  font-size: 15px;\n}\n#figgie-fast .ff-market-model {\n  display: flex;\n  justify-content: space-between;\n  gap: 6px;\n  padding: 2px 12px;\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-market-model b {\n  font-size: 11px;\n  font-weight: 500;\n}\n/* Base fair value is visible at the point of decision; bonus risk stays separate. */\n#figgie-fast .ff-fair-value {\n  color: var(--ff-ink);\n}\n#figgie-fast .ff-market-model .ff-fair-value b {\n  font-size: 13px;\n  font-weight: 700;\n}\n\n/* \u2500\u2500 Flow chart \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-chart {\n  display: block;\n  width: 100%;\n  height: 100%;\n  min-height: 0;\n}\n#figgie-fast .ff-chart text {\n  fill: var(--ff-dim);\n  font:\n    11px -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    sans-serif;\n}\n#figgie-fast [data-fill] {\n  cursor: crosshair;\n}\n#figgie-fast .ff-chart-meta {\n  display: flex;\n  justify-content: space-between;\n  gap: 8px;\n  min-height: 0;\n  padding: 0 12px;\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-flow-summary {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* \u2500\u2500 Top of book and take buttons \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Action columns: buy now at the ask or post a bid; sell now at the bid or post an ask. */\n#figgie-fast .ff-execution {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 10px;\n  padding: 2px 12px 0;\n}\n#figgie-fast .ff-side {\n  min-width: 0;\n}\n/* Top of book: participant colors identify owners; bid/ask colors retain meaning. */\n#figgie-fast .ff-counterparty {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 5px;\n  min-width: 0;\n  height: 20px;\n  margin-bottom: 3px;\n  overflow: hidden;\n  color: var(--ff-dim);\n  font-size: 11px;\n  white-space: nowrap;\n}\n#figgie-fast .ff-counterparty span:last-child {\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n#figgie-fast .ff-counterparty > span:first-child {\n  font-size: 13px;\n  font-weight: 600;\n}\n#figgie-fast .ff-counterparty > span[data-value='bid'] {\n  color: var(--ff-green);\n}\n#figgie-fast .ff-counterparty > span[data-value='ask'] {\n  color: var(--ff-red);\n}\n#figgie-fast .ff-counterparty > .ff-book-owner {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  max-width: 64%;\n  height: 19px;\n  padding: 1px 6px;\n  overflow: hidden;\n  border: 1px solid color-mix(in srgb, var(--ff-owner-color) 70%, transparent);\n  border-radius: 4px;\n  background: color-mix(in srgb, var(--ff-owner-color) 15%, var(--ff-panel));\n  color: var(--ff-ink);\n  font-size: 12px;\n  font-weight: 600;\n  line-height: 15px;\n  white-space: nowrap;\n}\n#figgie-fast .ff-book-owner > i {\n  display: block;\n  flex-shrink: 0;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--ff-owner-color);\n}\n#figgie-fast .ff-book-owner > span {\n  display: block;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n#figgie-fast .ff-book-owner[data-state='own'] {\n  padding: 0 5px;\n  border-width: 2px;\n  letter-spacing: 0.3px;\n}\n#figgie-fast .ff-book-owner[data-state='empty'] {\n  border-color: transparent;\n  background: transparent;\n  color: var(--ff-dim);\n  font-weight: 400;\n}\n#figgie-fast .ff-book-owner[data-state='empty'] > i {\n  display: none;\n}\n#figgie-fast .ff-book-owner[data-state='stale'] {\n  border-style: dashed;\n  opacity: 0.5;\n}\n#figgie-fast .ff-take {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  width: 100%;\n  height: 48px;\n  min-height: 48px;\n  padding: 4px 12px;\n  border: 1px solid #ffffff12;\n  border-radius: 4px;\n  font-weight: 500;\n}\n#figgie-fast .ff-take:active {\n  filter: brightness(1.3);\n}\n#figgie-fast .ff-take > span:first-child {\n  font-size: 12px;\n  white-space: nowrap;\n}\n/* Keep the decision price beside both actions. */\n#figgie-fast .ff-take-fair {\n  display: flex;\n  align-items: baseline;\n  gap: 4px;\n  color: var(--ff-dim);\n  font-size: 10px;\n  font-weight: 400;\n  white-space: nowrap;\n}\n#figgie-fast .ff-take-fair b {\n  color: var(--ff-ink);\n  font-size: 13px;\n  font-weight: 650;\n}\n#figgie-fast .ff-take .ff-price {\n  font-size: 32px;\n  font-weight: 600;\n  line-height: 1.05;\n  letter-spacing: -0.6px;\n}\n#figgie-fast .ff-sell {\n  background: var(--ff-red-bg);\n  color: var(--ff-red);\n}\n#figgie-fast .ff-buy {\n  background: var(--ff-green-bg);\n  color: var(--ff-green);\n}\n/* The best quote is the player's own: there is nothing to take. */\n#figgie-fast .ff-own {\n  background: var(--ff-soft);\n  color: var(--ff-dim);\n}\n#figgie-fast .ff-after {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 4px;\n  min-height: 16px;\n  margin-top: 3px;\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-after .ff-model-edge {\n  font-size: 11px;\n  font-weight: 500;\n  white-space: nowrap;\n}\n\n/* \u2500\u2500 Posting quotes \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-quoting {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 10px;\n  padding: 0 12px 6px;\n}\n#figgie-fast .ff-quote-stack {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n  padding-top: 3px;\n  border-top: 1px solid var(--ff-line);\n}\n#figgie-fast .ff-post-heading {\n  display: flex;\n  justify-content: space-between;\n  color: var(--ff-dim);\n  font-size: 10px;\n  line-height: 14px;\n}\n#figgie-fast [data-direction='buy'] .ff-post-heading {\n  color: var(--ff-green);\n}\n#figgie-fast [data-direction='sell'] .ff-post-heading {\n  color: var(--ff-red);\n}\n/* Fixed-price posts retain the buy/bid and sell/ask columns without replacing inputs. */\n#figgie-fast .ff-quote-presets {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  flex-shrink: 0;\n  gap: 4px;\n  min-width: 0;\n}\n#figgie-fast .ff-preset {\n  min-width: 0;\n  height: 24px;\n  min-height: 24px;\n  padding: 1px 3px;\n  border: 1px solid var(--ff-line);\n  border-radius: 4px;\n  background: var(--ff-panel);\n  font-size: 12px;\n  font-weight: 600;\n  font-variant-numeric: tabular-nums;\n  line-height: 20px;\n}\n#figgie-fast .ff-preset[data-preset='bid'] {\n  color: var(--ff-green);\n}\n#figgie-fast .ff-preset[data-preset='offer'] {\n  color: var(--ff-red);\n}\n#figgie-fast .ff-preset:not(:disabled):hover {\n  border-color: currentColor;\n  background: var(--ff-soft);\n}\n#figgie-fast .ff-preset:focus-visible {\n  outline: 2px solid currentColor;\n  outline-offset: 1px;\n}\n#figgie-fast .ff-quote-form {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  min-width: 0;\n}\n#figgie-fast .ff-quote-form input {\n  flex: 1 1 auto;\n  width: 0;\n  min-width: 0;\n  height: 32px;\n  padding: 6px 8px;\n  border: 1px solid var(--ff-line);\n  border-radius: 4px;\n  background: var(--ff-bg);\n  color: var(--ff-ink);\n  font-size: 14px;\n}\n#figgie-fast .ff-post {\n  height: 32px;\n  padding: 5px 10px;\n  border: 1px solid var(--ff-line);\n  border-radius: 4px;\n  background: var(--ff-panel);\n  font-size: 12px;\n  white-space: nowrap;\n}\n#figgie-fast .ff-quick {\n  flex-shrink: 0;\n  height: 32px;\n  padding: 4px 7px;\n  border: 1px solid var(--ff-line);\n  border-radius: 4px;\n  background: var(--ff-soft);\n  font-size: 11px;\n  white-space: nowrap;\n}\n#figgie-fast .ff-cancel {\n  flex-shrink: 0;\n  width: 28px;\n  height: 32px;\n  padding: 0;\n  border: 1px solid var(--ff-line);\n  border-radius: 4px;\n  background: var(--ff-soft);\n  color: var(--ff-dim);\n  font-size: 21px;\n  line-height: 1;\n  white-space: nowrap;\n}\n#figgie-fast .ff-quote-form input::placeholder {\n  opacity: 0.8;\n  color: var(--ff-dim);\n}\n/* Quote entry follows its displayed market side, including its posting color. */\n#figgie-fast .ff-quote-form[data-quote='bid'] input {\n  border-left: 2px solid var(--ff-green);\n}\n#figgie-fast .ff-quote-form[data-quote='ask'] input {\n  border-left: 2px solid var(--ff-red);\n}\n#figgie-fast .ff-post[data-kind='bid'] {\n  color: var(--ff-green);\n}\n#figgie-fast .ff-post[data-kind='offer'] {\n  color: var(--ff-red);\n}\n#figgie-fast .ff-quick[data-quick='bid'] {\n  color: var(--ff-green);\n}\n#figgie-fast .ff-quick[data-quick='offer'] {\n  color: var(--ff-red);\n}\n#figgie-fast .ff-cancel:not(:disabled):hover {\n  border-color: var(--ff-red);\n  color: var(--ff-red);\n}\n#figgie-fast .ff-resting-estimate {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  justify-content: space-between;\n  gap: 0 4px;\n  min-width: 0;\n  color: var(--ff-dim);\n  font-size: 10px;\n  line-height: 12px;\n  white-space: nowrap;\n}\n#figgie-fast .ff-resting-estimate > b {\n  grid-column: 1/-1;\n  font-size: 11px;\n  font-weight: 500;\n  white-space: nowrap;\n}\n#figgie-fast .ff-resting-estimate[data-state='unavailable'] {\n  opacity: 0.65;\n}\n\n/* \u2500\u2500 Player flow and trade tape \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* ui.js docks both under the markets: .ff-lower gains .ff-main-dock and the tape gains\n   .ff-main-tape. */\n#figgie-fast .ff-lower {\n  display: block;\n  border-top: 1px solid var(--ff-line);\n}\n#figgie-fast .ff-flow table {\n  table-layout: fixed;\n  width: calc(100% - 8px);\n}\n#figgie-fast .ff-lower th,\n#figgie-fast .ff-lower td {\n  padding: 4px 8px;\n  font-size: 11px;\n}\n#figgie-fast .ff-flow th:first-child {\n  width: 40%;\n}\n#figgie-fast .ff-flow td:first-child {\n  overflow: hidden;\n}\n#figgie-fast .ff-flow th:not(:first-child),\n#figgie-fast .ff-flow td:not(:first-child) {\n  padding-right: 6px;\n  padding-left: 4px;\n}\n#figgie-fast .ff-flow-player {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  width: 100%;\n  max-width: 100%;\n  vertical-align: middle;\n  white-space: nowrap;\n}\n#figgie-fast .ff-flow-player > i {\n  display: inline-block;\n  flex: 0 0 8px;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n}\n#figgie-fast .ff-flow-player > span {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n/* The public tape is one compressed, horizontally scrolling line of recent trades. */\n#figgie-fast .ff-main-tape {\n  min-height: 0;\n  overflow: hidden;\n  border-top: 1px solid var(--ff-line);\n  background: var(--ff-panel);\n}\n#figgie-fast .ff-main-tape .ff-section-heading {\n  height: 26px;\n  padding: 4px 12px;\n  line-height: 17px;\n}\n#figgie-fast #recent-trades {\n  display: flex;\n  align-items: center;\n  min-width: 0;\n  height: 36px;\n  min-height: 0;\n  overflow-x: auto;\n  overflow-y: hidden;\n  overscroll-behavior-x: contain;\n  scrollbar-width: thin;\n}\n/* Column headings of the undocked tape, which only the standalone page shows. */\n#figgie-fast .ff-trade-head {\n  display: grid;\n  grid-template-columns: 52px minmax(100px, 0.8fr) minmax(120px, 1.3fr) minmax(120px, 1.3fr) 60px;\n  align-items: center;\n  gap: 16px;\n  height: 18px;\n  padding: 0 14px;\n  border-bottom: 1px solid var(--ff-line);\n  background: #1d2a30;\n  color: var(--ff-dim);\n  font-size: 10px;\n}\n#figgie-fast .ff-trade-head > span:last-child {\n  text-align: right;\n}\n#figgie-fast .ff-main-tape .ff-trade-head {\n  display: none;\n}\n#figgie-fast .ff-main-tape .ff-trade-row {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  justify-content: flex-start;\n  gap: 5px;\n  min-width: 0;\n  max-width: 310px;\n  height: 30px;\n  padding: 2px 10px;\n  border-left: 1px solid var(--ff-line);\n  font-size: 11px;\n}\n#figgie-fast .ff-main-tape .ff-trade-index {\n  flex: 0 0 25px;\n  width: 25px;\n  color: var(--ff-dim);\n  font-size: 10px;\n}\n#figgie-fast .ff-trade-suit,\n#figgie-fast .ff-trade-party {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n#figgie-fast .ff-main-tape .ff-trade-suit {\n  flex: 0 0 17px;\n  overflow: visible;\n}\n#figgie-fast .ff-main-tape .ff-trade-suit .ff-suit-icon {\n  width: 16px;\n  height: 16px;\n  font-size: 15px;\n}\n#figgie-fast .ff-main-tape .ff-trade-party {\n  gap: 4px;\n  min-width: 0;\n  max-width: 82px;\n}\n#figgie-fast .ff-trade-party i {\n  flex-shrink: 0;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n}\n#figgie-fast .ff-party-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n#figgie-fast .ff-main-tape .ff-trade-arrow {\n  flex: 0 0 auto;\n  color: var(--ff-dim);\n}\n#figgie-fast .ff-main-tape .ff-trade-price {\n  flex: 0 0 auto;\n  color: var(--ff-dim);\n  white-space: nowrap;\n}\n#figgie-fast .ff-main-tape .ff-trade-price b {\n  color: var(--ff-ink);\n  font-size: 12px;\n  font-weight: 650;\n}\n#figgie-fast .ff-empty {\n  color: var(--ff-dim);\n  font-size: 12px;\n}\n#figgie-fast .ff-main-tape .ff-empty {\n  padding: 8px 14px;\n}\n\n/* \u2500\u2500 Notice and footer \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-notice {\n  min-height: 0;\n  padding: 6px 12px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  border-bottom: 1px solid var(--ff-line);\n  background: var(--ff-panel);\n  color: var(--ff-green);\n  font-size: 12px;\n  white-space: nowrap;\n}\n#figgie-fast footer {\n  display: flex;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 3px 12px;\n  overflow: hidden;\n  border-top: 1px solid var(--ff-line);\n  color: var(--ff-dim);\n  font-size: 10px;\n}\n\n/* \u2500\u2500 Model panel \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .ff-model-panel {\n  min-width: 0;\n  min-height: 0;\n  overflow: auto;\n  overscroll-behavior: contain;\n  border-left: 1px solid var(--ff-line);\n  background: var(--ff-panel);\n}\n#figgie-fast .ff-model-panel .ff-section-heading {\n  padding: 7px 10px;\n}\n#figgie-fast .ff-model-panel > .ff-section-heading {\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 2px;\n}\n#figgie-fast .ff-pnl-panel {\n  border-bottom: 1px solid var(--ff-line);\n}\n#figgie-fast .ff-pnl-panel .ff-section-heading {\n  display: flex;\n  flex-wrap: nowrap;\n  align-items: center;\n  gap: 6px;\n  padding: 7px 10px;\n  border-bottom: 0;\n  white-space: nowrap;\n}\n#figgie-fast .ff-pnl-panel .ff-section-heading > span {\n  font-size: 10px;\n}\n#figgie-fast .ff-pnl-panel strong {\n  margin-left: auto;\n  font-size: 20px;\n  letter-spacing: -0.5px;\n}\n/* Four conditional outcomes stay compact; trading cash and ante are included. */\n#figgie-fast .ff-scenario-heading {\n  display: flex;\n  justify-content: space-between;\n  gap: 5px;\n  padding: 2px 10px 5px;\n  color: var(--ff-ink);\n  font-size: 10px;\n}\n#figgie-fast .ff-scenario-heading > span {\n  color: var(--ff-dim);\n  font-size: 9px;\n}\n#figgie-fast .ff-pnl-scenarios {\n  padding: 0 10px 7px;\n  font-variant-numeric: tabular-nums;\n}\n#figgie-fast .ff-scenario-table {\n  table-layout: fixed;\n  width: 100%;\n  font-size: 10px;\n}\n#figgie-fast .ff-scenario-table th {\n  padding: 2px 3px 3px;\n  border: 0;\n  color: var(--ff-dim);\n  font-size: 10px;\n  font-weight: 400;\n  white-space: nowrap;\n}\n#figgie-fast .ff-scenario-table td {\n  padding: 2px 3px;\n  border: 0;\n  white-space: nowrap;\n}\n#figgie-fast .ff-scenario-table th:first-child {\n  width: 26px;\n}\n#figgie-fast .ff-scenario-table td:first-child {\n  width: 25px;\n}\n#figgie-fast .ff-scenario-table b {\n  font-variant-numeric: tabular-nums;\n}\n#figgie-fast .ff-scenario-table td > b {\n  font-size: 12px;\n  font-weight: 600;\n}\n#figgie-fast .ff-scenario-table .ff-scenario-weighted {\n  font-size: 11px;\n}\n#figgie-fast .ff-model-caption {\n  display: flex;\n  justify-content: space-between;\n  padding: 7px 10px 3px;\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-model-toggle {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  color: var(--ff-ink);\n  font-size: 10px;\n}\n#figgie-fast .ff-confidence {\n  padding: 4px 10px;\n  border-bottom: 1px solid var(--ff-line);\n  color: var(--ff-dim);\n  font-size: 10px;\n}\n#figgie-fast #ff-model-odds {\n  display: block;\n  min-height: 0;\n}\n#figgie-fast #ff-model-odds:empty {\n  min-height: 160px;\n}\n#figgie-fast .ff-odds-item {\n  padding: 5px 10px;\n}\n#figgie-fast .ff-odds-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  font-size: 12px;\n}\n#figgie-fast .ff-odds-heading > b {\n  font-size: 15px;\n  font-weight: 500;\n}\n#figgie-fast .ff-odds-track {\n  height: 4px;\n  margin-top: 3px;\n  overflow: hidden;\n  border-radius: 1px;\n  background: var(--ff-line);\n}\n#figgie-fast .ff-odds-fill {\n  height: 100%;\n  background: var(--ff-chart);\n}\n#figgie-fast .ff-odds-delta {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 2px;\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-model-prices {\n  font-size: 11px;\n}\n#figgie-fast .ff-model-prices th {\n  padding: 5px 8px;\n  font-size: 11px;\n  white-space: nowrap;\n}\n#figgie-fast .ff-model-prices td {\n  padding: 5px 8px;\n}\n#figgie-fast .ff-model-prices td:nth-child(3) {\n  color: var(--ff-ink);\n  font-weight: 500;\n}\n#figgie-fast .ff-model-estimate {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  gap: 4px 10px;\n  margin: 8px 10px;\n  padding-top: 8px;\n  border-top: 1px solid var(--ff-line);\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-model-estimate > b {\n  color: var(--ff-ink);\n  font-size: 15px;\n  font-weight: 500;\n}\n/* The static footnote is hidden; the sampling note under each goal suit reuses its class. */\n#figgie-fast .ff-model-footnote {\n  display: none;\n  padding: 0 12px 12px;\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-odds-item .ff-model-footnote {\n  display: block;\n  padding: 3px 0 0;\n  font-size: 10px;\n}\n#figgie-fast .ff-model-method {\n  padding: 7px 10px;\n  border-top: 1px solid var(--ff-line);\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .ff-model-method summary {\n  color: var(--ff-ink);\n  cursor: pointer;\n}\n#figgie-fast .ff-model-method dl {\n  margin-bottom: 0;\n}\n#figgie-fast .ff-model-method dt {\n  margin-top: 10px;\n  color: var(--ff-ink);\n  font-weight: 500;\n}\n#figgie-fast .ff-model-method dd {\n  margin: 3px 0 0;\n}\n\n/* \u2500\u2500 Recordings and diagnostics \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n#figgie-fast .diagnostics {\n  padding: 7px 10px;\n  border-top: 1px solid var(--ff-line);\n  color: var(--ff-dim);\n  font-size: 11px;\n}\n#figgie-fast .diagnostics textarea {\n  display: block;\n  width: 100%;\n  min-height: 220px;\n  margin-top: 10px;\n  border: 1px solid var(--ff-line);\n  background: var(--ff-bg);\n  color: var(--ff-ink);\n  font:\n    12px ui-monospace,\n    monospace;\n}\n#figgie-fast .ff-record-tools {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 5px;\n  margin: 8px 0;\n}\n#figgie-fast .ff-record-tools button,\n#figgie-fast .ff-result-input button,\n#figgie-fast .ff-result-input select {\n  padding: 5px;\n  border: 1px solid var(--ff-line);\n  border-radius: 3px;\n  background: var(--ff-soft);\n  color: var(--ff-ink);\n  font: 11px system-ui;\n}\n#figgie-fast #recording-details {\n  width: 100%;\n  overflow-wrap: anywhere;\n  font-size: 10px;\n}\n#figgie-fast .ff-result-input {\n  display: flex;\n  gap: 5px;\n  margin: 7px 0;\n}\n#figgie-fast #round-result-state {\n  color: var(--ff-green);\n  font-size: 11px;\n}\n\n/* \u2500\u2500 Control states \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Declared after the trading controls so that they win over control rules of equal weight,\n   and before the learning lab, which restyles its own controls. */\n#figgie-fast button:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n/* An order is on its way to Figgie. */\n#figgie-fast button[aria-busy='true'] {\n  outline: 1px solid var(--ff-chart);\n  opacity: 0.75;\n  cursor: wait;\n}\n#figgie-fast input:disabled {\n  opacity: 0.45;\n  cursor: default;\n}\n#figgie-fast input:focus {\n  border-color: var(--ff-green);\n}\n#figgie-fast .ff-take:focus-visible,\n#figgie-fast input:focus-visible {\n  outline: 2px solid var(--ff-green);\n  outline-offset: 1px;\n}\n\n/* \u2500\u2500 Value states \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Gains, losses and neutral values. Declared after the components so that a state color wins\n   over a component's own text color. */\n#figgie-fast .ff-positive,\n#figgie-fast .ff-inventory-item .ff-positive,\n#figgie-fast .ff-round-pnl .ff-positive,\n#figgie-fast .ff-pnl-panel .ff-positive {\n  color: var(--ff-green);\n}\n#figgie-fast .ff-negative,\n#figgie-fast .ff-inventory-item .ff-negative,\n#figgie-fast .ff-round-pnl .ff-negative,\n#figgie-fast .ff-pnl-panel .ff-negative {\n  color: var(--ff-red);\n}\n#figgie-fast .ff-zero {\n  color: var(--ff-dim);\n}\n/* A gain that exists only if the uncertain leader bonus arrives. */\n#figgie-fast [data-bonus-dependent='true']::after {\n  content: ' \u00b7 bonus';\n  color: #efc278;\n  font-size: 10px;\n  font-weight: 500;\n}\n\n/* \u2500\u2500 Learning lab \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* The learning lab is an overlay: it never compresses the trading grid. */\n#figgie-fast #ff-learning {\n  flex-shrink: 0;\n  border-color: #4c8e7a;\n  color: #a4e4d0;\n  white-space: nowrap;\n}\n#figgie-fast #ff-learning[hidden],\n#figgie-fast .ff-learning-overlay[hidden] {\n  display: none !important;\n}\n#figgie-fast .ff-learning-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 40;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 16px;\n  overscroll-behavior: contain;\n  background: #071216d9;\n}\n#figgie-fast .ff-learning-dialog {\n  display: flex;\n  flex-direction: column;\n  width: min(900px, 100%);\n  min-height: 0;\n  max-height: calc(100dvh - 32px);\n  overflow: hidden;\n  border: 1px solid #587078;\n  border-radius: 12px;\n  background: #203138;\n  box-shadow: 0 20px 80px #0009;\n  color: #e9f1f3;\n  font-size: 13px;\n  line-height: 1.5;\n}\n#figgie-fast .ff-learning-dialog > header {\n  display: flex;\n  flex-shrink: 0;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 16px 20px 10px;\n  border-bottom: 1px solid #3c5058;\n}\n#figgie-fast .ff-learning-dialog h2 {\n  margin: 2px 0;\n  font-size: 22px;\n  font-weight: 650;\n  line-height: 1.3;\n}\n#figgie-fast .ff-learn-eyebrow {\n  color: #92d4bf;\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 1.4px;\n}\n#figgie-fast .ff-learning-dialog button {\n  height: auto;\n  min-height: 34px;\n  padding: 7px 12px;\n  border: 1px solid #56717a;\n  border-radius: 5px;\n  background: #2b424a;\n  color: #ecf4f6;\n  font-size: 12px;\n  line-height: 1.3;\n  cursor: pointer;\n}\n#figgie-fast .ff-learning-dialog button:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n#figgie-fast .ff-learning-dialog button:focus-visible,\n#figgie-fast .ff-learning-dialog input:focus-visible,\n#figgie-fast .ff-learning-dialog select:focus-visible,\n#figgie-fast .ff-learning-dialog textarea:focus-visible,\n#figgie-fast .ff-learning-dialog summary:focus-visible {\n  outline: 2px solid #8ce4c4;\n  outline-offset: 2px;\n}\n#figgie-fast .ff-learning-dialog [data-learn='close'] {\n  padding: 0 10px;\n  border: 0;\n  background: transparent;\n  font-size: 24px;\n}\n#figgie-fast .ff-learn-clock {\n  flex-shrink: 0;\n  padding: 7px 20px;\n  background: #273d44;\n  color: #c0d1d6;\n  font-size: 11px;\n}\n#figgie-fast #ff-learn-body {\n  min-height: 0;\n  padding: 18px 20px;\n  overflow: auto;\n  overscroll-behavior: contain;\n  scrollbar-width: thin;\n}\n#figgie-fast .ff-learning-dialog p {\n  margin: 8px 0 14px;\n  line-height: 1.5;\n}\n#figgie-fast .ff-learn-step {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px;\n}\n#figgie-fast .ff-learn-step b {\n  font-size: 16px;\n}\n#figgie-fast .ff-learn-step > span {\n  color: #aebfc6;\n  font-size: 11px;\n}\n#figgie-fast .ff-learn-prob-inputs {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 12px;\n  margin-top: 16px;\n}\n#figgie-fast .ff-learn-prob-inputs label {\n  padding: 12px;\n  border: 1px solid #425a64;\n  border-radius: 6px;\n  background: #283d45;\n  font-weight: 600;\n}\n#figgie-fast .ff-learn-prob-inputs label > span:last-child {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  margin-top: 8px;\n  color: #aebfc6;\n}\n#figgie-fast .ff-learning-dialog input,\n#figgie-fast .ff-learning-dialog select,\n#figgie-fast .ff-learning-dialog textarea {\n  min-width: 0;\n  max-width: 100%;\n  padding: 7px;\n  border: 1px solid #56717a;\n  border-radius: 4px;\n  background: #14272e;\n  color: #edf4f6;\n  font: inherit;\n}\n#figgie-fast .ff-learn-prob-inputs input {\n  width: 100%;\n  font-size: 22px;\n  font-variant-numeric: tabular-nums;\n}\n#figgie-fast .ff-learn-suit {\n  display: inline-block;\n  margin-right: 3px;\n  color: #d8e5e9;\n  font-size: 18px;\n  line-height: 1;\n  vertical-align: middle;\n}\n#figgie-fast .ff-learn-suit.ff-suit-red {\n  color: #ff8da4;\n}\n#figgie-fast .ff-learn-total {\n  margin: 7px 0 16px;\n  color: #aebfc6;\n  font-size: 11px;\n}\n#figgie-fast .ff-learn-guess {\n  margin-bottom: 14px;\n  padding-top: 12px;\n  border-top: 1px solid #40545d;\n}\n#figgie-fast .ff-learn-guess summary {\n  color: #c7d8df;\n  cursor: pointer;\n}\n#figgie-fast .ff-learn-guess-fields {\n  display: grid;\n  grid-template-columns: 2fr 1fr 1fr;\n  gap: 12px;\n  margin-top: 12px;\n}\n#figgie-fast .ff-learn-guess-fields label {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  font-size: 11px;\n}\n#figgie-fast .ff-learn-reason {\n  display: block;\n  font-size: 12px;\n}\n#figgie-fast .ff-learn-reason > span {\n  color: #aebfc6;\n  font-size: 10px;\n}\n#figgie-fast .ff-learn-reason textarea {\n  display: block;\n  width: 100%;\n  max-height: 150px;\n  margin-top: 6px;\n  resize: vertical;\n}\n#figgie-fast .ff-learn-save {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 12px;\n  margin: 16px 0 8px;\n}\n#figgie-fast .ff-learn-save button,\n#figgie-fast .ff-learning-dialog [data-learn='continue'] {\n  border-color: #5aab8c;\n  background: #295747;\n  color: #c6ffe6;\n  font-weight: 650;\n}\n#figgie-fast #ff-learn-availability {\n  color: #b4c8ce;\n  font-size: 11px;\n}\n#figgie-fast #ff-learn-error,\n#figgie-fast .ff-learn-warning {\n  color: #ffc18b;\n  font-size: 12px;\n}\n#figgie-fast .ff-learn-small {\n  color: #aebfc6;\n  font-size: 11px;\n  line-height: 1.5;\n}\n#figgie-fast .ff-learn-reveals {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 7px;\n  margin: 14px 0;\n}\n#figgie-fast .ff-learn-player {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  white-space: nowrap;\n}\n#figgie-fast .ff-learn-player i {\n  display: inline-block;\n  flex-shrink: 0;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n}\n#figgie-fast .ff-learn-scroll {\n  margin-top: 16px;\n  overflow-x: auto;\n  scrollbar-width: thin;\n}\n#figgie-fast .ff-learn-table {\n  table-layout: auto;\n  border-collapse: collapse;\n  width: 100%;\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n  line-height: 1.5;\n  white-space: nowrap;\n}\n#figgie-fast .ff-learn-table caption {\n  padding-bottom: 8px;\n  color: #cfe1e7;\n  font-size: 13px;\n  font-weight: 650;\n  text-align: left;\n}\n#figgie-fast .ff-learn-table th,\n#figgie-fast .ff-learn-table td {\n  padding: 9px 10px;\n  border-bottom: 1px solid #40545d;\n  font-weight: 400;\n  text-align: right;\n  vertical-align: middle;\n}\n#figgie-fast .ff-learn-table th:first-child {\n  padding-left: 0;\n  text-align: left;\n}\n#figgie-fast .ff-learn-table thead {\n  color: #aebfc6;\n  font-size: 11px;\n}\n#figgie-fast .ff-learn-table .ff-learn-suit {\n  font-size: 15px;\n}\n#figgie-fast .ff-learn-table td small {\n  display: block;\n  color: #aebfc6;\n  font-size: 10px;\n}\n#figgie-fast .ff-learn-known {\n  color: #9fe7cd;\n}\n#figgie-fast .ff-learn-actual {\n  background: #2c473f;\n  color: #c8ffe8;\n}\n#figgie-fast .ff-learn-score {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  margin: 14px 0;\n  padding: 12px 14px;\n  border: 1px solid #538876;\n  border-radius: 6px;\n  background: #2c473f;\n}\n#figgie-fast .ff-learn-score small {\n  display: block;\n  color: #b2c9c0;\n  font-size: 10px;\n}\n#figgie-fast .ff-learn-feedback {\n  padding: 10px 14px;\n  border-left: 3px solid #74bbd9;\n  border-radius: 3px;\n  background: #2b414b;\n}\n#figgie-fast .ff-learn-payoff {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n  margin: 18px 0;\n}\n#figgie-fast .ff-learn-payoff > div {\n  padding: 14px;\n  border: 1px solid #455f68;\n  border-radius: 6px;\n  background: #192c32;\n}\n#figgie-fast .ff-learn-payoff span {\n  color: #c6d6db;\n  font-size: 12px;\n}\n#figgie-fast .ff-learn-payoff strong {\n  display: block;\n  font-size: 26px;\n  line-height: 1.5;\n}\n#figgie-fast .ff-learn-payoff small {\n  display: block;\n  color: #aebfc6;\n  font-size: 10px;\n}\n#figgie-fast .ff-learn-reflect {\n  margin: 18px 0;\n  padding-top: 14px;\n  border-top: 1px solid #40545d;\n  color: #d0e0e5;\n  font-size: 12px;\n}\n#figgie-fast .ff-learning-dialog > footer {\n  display: flex;\n  flex-shrink: 0;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 12px 20px;\n  border-top: 1px solid #40545d;\n  background: #192b32;\n}\n#figgie-fast #ff-learn-live {\n  color: #b7c8ce;\n  font-size: 11px;\n}\n\n/* \u2500\u2500 Responsive layouts \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n/* Touch input: larger targets. The height tiers and the desktop layout below take precedence\n   where they apply. */\n@media (pointer: coarse) {\n  #figgie-fast input[type='checkbox'] {\n    width: 20px;\n    height: 20px;\n  }\n  #figgie-fast .ff-quote-form input {\n    height: auto;\n    min-height: 44px;\n    font-size: 16px;\n  }\n  #figgie-fast .ff-post {\n    height: auto;\n    min-height: 44px;\n  }\n}\n\n/* At most 1100px wide: a slimmer model panel, suit symbols without their names, tighter\n   quote controls. */\n@media (max-width: 1100px) {\n  #figgie-fast .ff-workspace {\n    display: none;\n  }\n  #figgie-fast .ff-inventory-item > span::first-letter {\n    font-size: 15px;\n  }\n  #figgie-fast .ff-inventory-item .ff-suit-name {\n    display: none;\n  }\n  #figgie-fast .ff-model-workspace {\n    grid-template-columns: minmax(0, 1fr) 230px;\n  }\n  #figgie-fast .ff-quote-form {\n    gap: 3px;\n  }\n  #figgie-fast .ff-post,\n  #figgie-fast .ff-quick {\n    padding-right: 4px;\n    padding-left: 4px;\n    font-size: 10px;\n  }\n  #figgie-fast .ff-cancel {\n    width: 22px;\n  }\n}\n\n/* At most 900px wide: larger model prices, and the evidence notes become a two-column list. */\n@media (max-width: 900px) {\n  #figgie-fast .ff-model-panel .ff-model-prices {\n    font-size: 12px;\n  }\n  #figgie-fast .ff-model-estimate {\n    max-width: 400px;\n  }\n  #figgie-fast .ff-model-method dl {\n    display: grid;\n    grid-template-columns: 150px minmax(0, 1fr);\n    gap: 8px;\n  }\n  #figgie-fast .ff-model-method dt {\n    margin-top: 0;\n  }\n  #figgie-fast .ff-model-method dd {\n    margin: 0;\n  }\n}\n\n/* At most 650px wide: the header wraps, the inventory tightens and the evidence notes stack\n   again. */\n@media (max-width: 650px) {\n  /* Header */\n  #figgie-fast .ff-header {\n    flex-wrap: wrap;\n  }\n  #figgie-fast .ff-workspace {\n    margin-left: 4px;\n  }\n\n  /* Account bar */\n  #figgie-fast .ff-keys {\n    margin-left: auto;\n  }\n\n  /* Inventory strip */\n  #figgie-fast .ff-inventory-label {\n    grid-column: 1;\n  }\n  #figgie-fast #ff-inventory-items {\n    gap: 4px;\n  }\n  #figgie-fast .ff-inventory-item {\n    padding-left: 8px;\n  }\n  #figgie-fast .ff-inventory-item:first-child {\n    padding-left: 0;\n    border-left: 0;\n  }\n\n  /* Market panel */\n  #figgie-fast .ff-market:nth-child(odd) {\n    border-right: 0;\n  }\n\n  /* Model panel */\n  #figgie-fast .ff-model-method dl {\n    display: block;\n  }\n  #figgie-fast .ff-model-method dt {\n    margin-top: 10px;\n  }\n  #figgie-fast .ff-model-method dd {\n    margin-top: 3px;\n  }\n}\n\n/* At most 600px wide: the learning lab uses the whole width. */\n@media (max-width: 600px) {\n  #figgie-fast .ff-learning-overlay {\n    padding: 6px;\n  }\n  #figgie-fast .ff-learning-dialog {\n    max-height: calc(100dvh - 12px);\n  }\n  #figgie-fast .ff-learning-dialog > header {\n    padding: 12px;\n  }\n  #figgie-fast .ff-learning-dialog h2 {\n    font-size: 18px;\n  }\n  #figgie-fast .ff-learn-clock {\n    padding: 7px 12px;\n  }\n  #figgie-fast #ff-learn-body {\n    padding: 12px;\n  }\n  #figgie-fast .ff-learn-prob-inputs {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 8px;\n  }\n  #figgie-fast .ff-learn-guess-fields {\n    grid-template-columns: 1fr;\n  }\n  #figgie-fast .ff-learn-payoff {\n    grid-template-columns: 1fr;\n  }\n  #figgie-fast .ff-learning-dialog > footer {\n    padding: 12px;\n  }\n}\n\n/* At most 380px wide: the inventory wraps to two columns and the shortcut hints are hidden. */\n@media (max-width: 380px) {\n  #figgie-fast kbd {\n    display: none;\n  }\n  #figgie-fast #ff-inventory-items {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    gap: 10px;\n  }\n  #figgie-fast .ff-inventory-item:nth-child(3) {\n    padding-left: 0;\n    border-left: 0;\n  }\n}\n\n/* Wide but at most 740px tall: shorter take buttons and quote controls. The desktop layout\n   below overrides whatever it also sets. */\n@media (min-width: 761px) and (max-height: 740px) {\n  #figgie-fast {\n    grid-template-rows: 32px 24px 40px 22px minmax(0, 1fr) 100px 24px 18px;\n  }\n  #figgie-fast .ff-counterparty {\n    margin-bottom: 1px;\n    font-size: 10px;\n  }\n  #figgie-fast .ff-counterparty > .ff-book-owner {\n    height: 17px;\n    font-size: 11px;\n    line-height: 13px;\n  }\n  #figgie-fast .ff-take {\n    height: 38px;\n    min-height: 38px;\n  }\n  #figgie-fast .ff-take .ff-price {\n    font-size: 29px;\n  }\n  #figgie-fast .ff-after {\n    margin-top: 1px;\n    font-size: 10px;\n  }\n  #figgie-fast .ff-quoting {\n    padding-bottom: 2px;\n  }\n  #figgie-fast .ff-quote-form input,\n  #figgie-fast .ff-post,\n  #figgie-fast .ff-quick,\n  #figgie-fast .ff-cancel {\n    height: 28px;\n  }\n  #figgie-fast .ff-main-tape .ff-section-heading {\n    height: 22px;\n  }\n}\n\n/* Wide but at most 680px tall: tighter still. */\n@media (min-width: 761px) and (max-height: 680px) {\n  #figgie-fast .ff-market {\n    grid-template-rows: 22px 16px minmax(12px, 1fr) 10px 72px 70px;\n  }\n  #figgie-fast .ff-chart-meta {\n    font-size: 9px;\n  }\n  #figgie-fast .ff-counterparty {\n    height: 16px;\n  }\n  #figgie-fast .ff-counterparty > .ff-book-owner {\n    height: 15px;\n    padding-top: 0;\n    padding-bottom: 0;\n    font-size: 10px;\n    line-height: 11px;\n  }\n  #figgie-fast .ff-after .ff-model-edge {\n    font-size: 10px;\n  }\n  #figgie-fast .ff-post-heading {\n    line-height: 12px;\n  }\n}\n\n/* The undocked tape's column headings are shorter at these heights (standalone page only). */\n@media (min-width: 761px) and (min-height: 601px) and (max-height: 680px),\n  (min-width: 761px) and (min-height: 741px) {\n  #figgie-fast .ff-trade-head {\n    height: 16px;\n  }\n}\n\n/* At least 1000px wide and at most 700px tall: no gap above the take buttons. */\n@media (min-width: 1000px) and (max-height: 700px) {\n  #figgie-fast .ff-execution {\n    padding-top: 0;\n  }\n}\n\n/* Compact: too narrow or too short for the fixed grid. The page scrolls, each market keeps a\n   fixed height, and the model panel follows the markets. */\n@media (max-width: 760px), (max-height: 520px) {\n  /* Host and root */\n  :host {\n    overflow: auto;\n  }\n  #figgie-fast {\n    display: block;\n    height: auto;\n    min-height: 100%;\n    overflow: visible;\n  }\n\n  /* Header */\n  #figgie-fast .ff-header {\n    min-height: 36px;\n  }\n\n  /* Account bar */\n  #figgie-fast .ff-account {\n    flex-wrap: wrap;\n    min-height: 36px;\n  }\n\n  /* Inventory strip */\n  #figgie-fast .ff-inventory {\n    grid-template-columns: 85px minmax(0, 1fr) 90px;\n    min-height: 36px;\n  }\n\n  /* Player legend */\n  #figgie-fast .ff-buyer-legend {\n    min-height: 36px;\n  }\n\n  /* Workspace */\n  #figgie-fast .ff-model-workspace {\n    display: block;\n    overflow: visible;\n  }\n\n  /* Market panel */\n  #figgie-fast .ff-market {\n    grid-template-rows: 28px 18px minmax(28px, 1fr) 14px 90px 108px;\n    height: 360px;\n  }\n\n  /* Player flow and trade tape */\n  #figgie-fast .ff-main-dock {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr);\n  }\n  #figgie-fast .ff-main-dock .ff-flow {\n    overflow: auto;\n  }\n  #figgie-fast .ff-main-dock .ff-flow table {\n    width: 100%;\n  }\n  #figgie-fast .ff-main-tape {\n    min-height: 66px;\n  }\n  #figgie-fast .ff-trade-head {\n    grid-template-columns: 32px 75px minmax(70px, 1fr) minmax(70px, 1fr) 40px;\n    gap: 6px;\n    padding-right: 8px;\n    padding-left: 8px;\n  }\n  #figgie-fast .ff-trade-suit {\n    gap: 4px;\n  }\n\n  /* Model panel */\n  #figgie-fast .ff-model-panel {\n    overflow: visible;\n  }\n}\n\n/* Desktop: trading rows. Each market is one row of identity, chart and controls, so\n   accumulation stays readable and the execution controls sit side by side. The charts\n   replace the player legend and the flow table, and the tape becomes a single strip. */\n@media (min-width: 761px) and (min-height: 521px) {\n  /* Host and root */\n  #figgie-fast {\n    grid-template-rows: 38px 26px 42px 0 minmax(0, 1fr) 40px 24px 18px;\n  }\n\n  /* Account bar */\n  #figgie-fast .ff-account {\n    padding-top: 0;\n    padding-bottom: 0;\n    line-height: 18px;\n  }\n  #figgie-fast .ff-round-pnl b {\n    line-height: 18px;\n  }\n\n  /* Inventory strip */\n  #figgie-fast .ff-inventory {\n    grid-template-columns: 85px minmax(0, 1fr) 145px;\n    min-height: 0;\n    padding: 2px 12px;\n  }\n  #figgie-fast .ff-inventory-label {\n    line-height: 14px;\n  }\n  #figgie-fast .ff-inventory-label span {\n    line-height: 12px;\n  }\n  #figgie-fast .ff-inventory-item {\n    white-space: nowrap;\n  }\n  #figgie-fast .ff-inventory-item strong {\n    line-height: 24px;\n  }\n  #figgie-fast .ff-inventory-value {\n    display: flex;\n    align-items: center;\n    justify-content: flex-end;\n    gap: 6px;\n    min-height: 0;\n    line-height: 14px;\n    white-space: nowrap;\n  }\n  #figgie-fast .ff-inventory-value strong {\n    margin-left: 0;\n    line-height: 24px;\n  }\n\n  /* Player legend */\n  #figgie-fast .ff-buyer-legend {\n    visibility: hidden;\n    height: 0;\n    min-height: 0;\n    padding: 0;\n    border: 0;\n  }\n\n  /* Workspace */\n  #figgie-fast .ff-markets {\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-rows: repeat(4, minmax(138px, 1fr));\n    overflow: auto;\n  }\n\n  /* Market panel */\n  #figgie-fast .ff-market {\n    grid-template-columns: minmax(90px, 0.45fr) minmax(160px, 1fr) minmax(400px, 1.9fr);\n    grid-template-rows: 60px minmax(76px, 1fr);\n  }\n  #figgie-fast .ff-market-heading {\n    grid-column: 1;\n    grid-row: 1;\n    flex-direction: column;\n    align-items: flex-start;\n    justify-content: center;\n    gap: 3px;\n    padding: 5px 10px;\n  }\n  #figgie-fast .ff-market-name {\n    font-size: 14px;\n    white-space: nowrap;\n  }\n  #figgie-fast .ff-market-numbers {\n    gap: 8px;\n    font-size: 10px;\n    white-space: nowrap;\n  }\n  #figgie-fast .ff-market-numbers b {\n    margin-left: 2px;\n    font-size: 12px;\n  }\n  #figgie-fast .ff-market-model {\n    grid-column: 1;\n    grid-row: 2;\n    flex-direction: column;\n    align-items: flex-start;\n    justify-content: flex-start;\n    gap: 1px;\n    padding: 0 10px;\n    font-size: 10px;\n    line-height: 14px;\n  }\n  #figgie-fast .ff-market-model .ff-fair-value b {\n    font-size: 15px;\n  }\n\n  /* Flow chart */\n  #figgie-fast .ff-chart {\n    grid-column: 2;\n    grid-row: 1/3;\n    align-self: stretch;\n    height: calc(100% - 17px);\n    margin-top: 17px;\n    border-left: 1px solid var(--ff-line);\n  }\n  #figgie-fast .ff-chart-meta {\n    grid-column: 2;\n    grid-row: 1;\n    align-items: center;\n    align-self: start;\n    gap: 6px;\n    padding: 3px 5px 0 7px;\n    overflow: hidden;\n    font-size: 10px;\n    line-height: 12px;\n    white-space: nowrap;\n  }\n  #figgie-fast .ff-chart-meta > span:first-child {\n    flex-shrink: 0;\n  }\n  #figgie-fast .ff-chart-meta > span:last-child {\n    display: block;\n  }\n\n  /* Top of book and take buttons */\n  #figgie-fast .ff-execution {\n    grid-column: 3;\n    grid-row: 1;\n    padding: 3px 10px 0;\n  }\n  #figgie-fast .ff-counterparty {\n    height: 13px;\n    margin-bottom: 1px;\n    font-size: 10px;\n    line-height: 12px;\n  }\n  #figgie-fast .ff-take {\n    height: 30px;\n    min-height: 30px;\n    padding: 2px 8px;\n  }\n  #figgie-fast .ff-take .ff-price {\n    font-size: 25px;\n  }\n  #figgie-fast .ff-after {\n    gap: 3px;\n    min-height: 12px;\n    margin-top: 1px;\n    font-size: 10px;\n    line-height: 12px;\n  }\n  #figgie-fast .ff-after > span {\n    white-space: nowrap;\n  }\n  #figgie-fast .ff-after .ff-model-edge {\n    font-size: 10px;\n  }\n\n  /* Posting quotes */\n  #figgie-fast .ff-quoting {\n    grid-column: 3;\n    grid-row: 2;\n    padding: 1px 10px 3px;\n  }\n  #figgie-fast .ff-quote-stack {\n    align-content: start;\n    gap: 0;\n    padding: 0;\n    border: 0;\n  }\n  #figgie-fast .ff-post-heading {\n    display: none;\n  }\n  #figgie-fast .ff-quote-presets {\n    margin-bottom: 3px;\n  }\n  #figgie-fast .ff-preset {\n    height: 22px;\n    min-height: 22px;\n    font-size: 11px;\n    line-height: 18px;\n  }\n  #figgie-fast .ff-quote-form {\n    gap: 4px;\n  }\n  #figgie-fast .ff-quote-form input,\n  #figgie-fast .ff-post,\n  #figgie-fast .ff-quick,\n  #figgie-fast .ff-cancel {\n    height: 25px;\n    min-height: 25px;\n    padding-top: 2px;\n    padding-bottom: 2px;\n  }\n  #figgie-fast .ff-resting-estimate {\n    padding-top: 1px;\n    font-size: 9px;\n  }\n  #figgie-fast .ff-resting-estimate > b {\n    font-size: 10px;\n  }\n\n  /* Player flow and trade tape */\n  #figgie-fast .ff-main-dock {\n    display: block;\n    min-height: 0;\n    overflow: hidden;\n    background: var(--ff-panel);\n  }\n  #figgie-fast .ff-main-dock .ff-section-heading {\n    flex-wrap: nowrap;\n    white-space: nowrap;\n  }\n  #figgie-fast .ff-main-dock .ff-section-heading > span {\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n  #figgie-fast .ff-main-dock .ff-flow {\n    display: none;\n  }\n  #figgie-fast .ff-main-tape {\n    display: grid;\n    grid-template-columns: 92px minmax(0, 1fr);\n    align-items: center;\n    height: 100%;\n  }\n  #figgie-fast .ff-main-dock > .ff-main-tape {\n    min-width: 0;\n    border-top: 0;\n  }\n  #figgie-fast .ff-main-tape .ff-section-heading {\n    display: flex;\n    flex-direction: column;\n    align-items: flex-start;\n    justify-content: center;\n    gap: 1px;\n    height: 100%;\n    padding: 0 10px;\n    border: 0;\n    font-size: 11px;\n    line-height: 13px;\n  }\n  #figgie-fast .ff-main-tape .ff-section-heading > span {\n    display: block;\n    font-size: 9px;\n    line-height: 11px;\n  }\n  #figgie-fast #recent-trades {\n    margin: 2px 0;\n  }\n  #figgie-fast .ff-main-tape .ff-trade-suit {\n    white-space: nowrap;\n  }\n}\n"};
